/* Vues : Finances, Calendrier, Appareils, Notifications, Assistant, Journal, Paramètres. */
import { Store, Repo, Selectors, Utils, Taxonomy, APP_VERSION } from './core.js';
import { icon, badge, progressBar, emptyState, sectionHeader, Charts } from './ui.js';
import { ViewState } from './view-state.js';
import { Sophie } from './sophie.js';
import { TTS } from './tts.js';
import { SophieAvatar } from './sophie-avatar.js';

const actionButton = (action, id, name = 'edit', label = 'Modifier') => `<button class="icon-button subtle" data-action="${action}" data-id="${Utils.esc(id || '')}" aria-label="${Utils.esc(label)}" title="${Utils.esc(label)}">${icon(name, 17)}</button>`;
const priorityTone = priority => ({ Critique: 'critique', Haute: 'haute', Basse: 'basse' }[priority] || 'normale');
const eventColors = { Personnel: '#A78BFA', Travail: '#35BDE0', Sport: '#37D6A0', SPV: '#FF9A5A', Projet: '#65A9FF', Finance: '#E7C873', Santé: '#EC6A88', Autre: '#6E8795' };
const WIDGET_LABELS = { goals: 'Objectifs', sport: 'Sport', projects: 'Projets', finance: 'Finances', weather: 'Météo', news: 'Point actualité', calendar: 'Calendrier', focus: 'Focus & minuteur', reminders: 'Rappels', habits: 'Habitudes', spotify: 'Spotify', devices: 'Appareils', notifications: 'Notifications', journal: 'Journal' };

export function Finances() {
  const month = ViewState.financeMonth || Utils.monthKey(); const stats = Selectors.finance(month);
  const transactions = [...stats.monthly].sort((a, b) => b.date.localeCompare(a.date));
  const byCategory = Object.entries(stats.monthly.filter(t => t.type === 'expense').reduce((groups, tx) => { groups[tx.category || 'Autre'] = (groups[tx.category || 'Autre'] || 0) + Number(tx.amount || 0); return groups; }, {})).map(([label, value]) => ({ label, value })).sort((a, b) => b.value - a.value);
  const months = Array.from({ length: 6 }, (_, index) => {
    const date = new Date(`${month}-01T12:00:00`); date.setMonth(date.getMonth() - (5 - index)); const key = Utils.monthKey(date); const item = Selectors.finance(key);
    return { label: new Intl.DateTimeFormat('fr-FR', { month: 'short' }).format(date).replace('.', ''), value: item.expense, secondary: item.income, key };
  });
  const subscriptions = Store.data.finance.subscriptions || [], debts = Store.data.finance.debts || [];
  const add = `<button class="button ghost" data-action="transaction-new" data-type="expense">${icon('plus', 17)} Dépense</button><button class="button primary" data-action="transaction-new" data-type="income">${icon('plus', 17)} Revenu</button>`;
  return `<div class="page-view finance-view">${sectionHeader('RESSOURCES / FLUX MENSUELS', 'Finances', 'Une saisie manuelle transparente, modifiable et sans connexion bancaire simulée.', add)}
    <div class="finance-disclosure reveal">${icon('lock', 17)}<span><strong>Données saisies localement uniquement.</strong> Aucun compte bancaire n’est connecté et aucun montant n’est récupéré auprès d’un établissement.</span><label>Mois analysé <input type="month" value="${month}" data-view-filter="finance-month"></label></div>
    <section class="kpi-grid finance-kpis five reveal"><div class="kpi-card"><span>Revenus · ${Utils.monthLabel(month)}</span><strong>${Utils.money(stats.income)}</strong><small>${stats.monthly.filter(t => t.type === 'income').length} opération(s)</small></div><div class="kpi-card"><span>Dépenses</span><strong>${Utils.money(stats.expense)}</strong><small>${stats.monthly.filter(t => t.type === 'expense').length} opération(s)</small></div><div class="kpi-card ${stats.balance < 0 ? 'warning' : ''}"><span>Solde mensuel</span><strong>${Utils.money(stats.balance)}</strong><small>Revenus moins dépenses</small></div><div class="kpi-card ${stats.remaining < 0 ? 'warning' : ''}"><span>Budget restant</span><strong>${stats.budget ? Utils.money(stats.remaining) : 'Non défini'}</strong><small>${stats.budget ? `${Math.round(stats.budgetRatio)} % utilisé` : 'Définissez votre enveloppe'}</small></div><div class="kpi-card"><span>Taux d’épargne indicatif</span><strong>${Utils.round(stats.savingsRate, 1)}<small>%</small></strong><small>Part non dépensée des revenus</small></div></section>
    <section class="finance-analytics"><article class="panel chart-panel reveal"><header class="panel-header"><div><span class="micro-label">TENDANCE / 6 MOIS</span><h2>Revenus et dépenses</h2></div><div class="legend-inline"><span><i class="income"></i>Revenus</span><span><i class="expense"></i>Dépenses</span></div></header>${Charts.bars(months, { color: 'var(--orange)', secondary: 'var(--accent)' })}</article><article class="panel reveal"><header class="panel-header"><div><span class="micro-label">ALLOCATION</span><h2>Répartition des dépenses</h2></div></header>${Charts.donut(byCategory, 'dépensés')}</article></section>
    <section class="panel reveal"><header class="panel-header"><div><span class="micro-label">PILOTAGE</span><h2>Budget & épargne</h2></div><button class="button ghost small" data-action="budget-edit">${icon('edit', 15)} Modifier les seuils</button></header><div class="budget-control"><div><span>Budget de dépenses mensuel</span><strong>${stats.budget ? Utils.money(stats.budget) : 'Aucun seuil'}</strong></div><div class="budget-progress">${progressBar(stats.budgetRatio, stats.budget ? `${Utils.money(stats.expense)} engagés sur ${Utils.money(stats.budget)}` : 'Le ratio sera calculé après définition du budget', stats.budgetRatio > 100 ? 'danger' : '')}</div><div><span>Cap d’épargne mensuel</span><strong>${Utils.money(Store.data.finance.savingsTarget || 0)}</strong><small>${Math.max(0, stats.balance) >= Number(Store.data.finance.savingsTarget || 0) && Number(Store.data.finance.savingsTarget) > 0 ? 'Cap atteint sur le solde du mois' : 'Comparé au solde positif du mois'}</small></div></div></section>
    <section class="panel transactions-panel reveal"><header class="panel-header"><div><span class="micro-label">JOURNAL DES OPÉRATIONS</span><h2>${Utils.monthLabel(month)}</h2></div><span class="result-count">${transactions.length} opération${transactions.length > 1 ? 's' : ''}</span></header>${transactions.length ? `<div class="responsive-table"><table><thead><tr><th>Date</th><th>Libellé</th><th>Catégorie</th><th>Type</th><th class="align-right">Montant</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${transactions.map(tx => `<tr><td>${Utils.formatDate(tx.date)}</td><td><strong>${Utils.esc(tx.label)}</strong>${tx.notes ? `<small>${Utils.esc(tx.notes)}</small>` : ''}</td><td>${badge(tx.category)}</td><td><span class="transaction-type ${tx.type}">${tx.type === 'income' ? 'Revenu' : 'Dépense'}</span></td><td class="align-right amount ${tx.type}">${tx.type === 'income' ? '+' : '−'} ${Utils.money(tx.amount)}</td><td><div class="row-actions">${actionButton('transaction-edit', tx.id)}${actionButton('transaction-delete', tx.id, 'trash', 'Supprimer l’opération')}</div></td></tr>`).join('')}</tbody></table></div>` : emptyState('Aucune opération ce mois-ci', 'Ajoutez un revenu ou une dépense, ou choisissez un autre mois.', add, 'wallet')}</section>
    <section class="finance-secondary"><article class="panel reveal"><header class="panel-header"><div><span class="micro-label">RÉCURRENCES</span><h2>Abonnements</h2></div><button class="button ghost small" data-action="subscription-new">${icon('plus', 15)} Ajouter</button></header>${subscriptions.length ? `<div class="subscription-list">${subscriptions.map(sub => `<div class="subscription-row"><button class="task-check ${sub.active ? 'done' : ''}" data-action="subscription-toggle" data-id="${sub.id}" aria-label="${sub.active ? 'Suspendre' : 'Activer'} ${Utils.esc(sub.name)}">${icon('check', 13)}</button><div><strong>${Utils.esc(sub.name)}</strong><small>${Utils.esc(sub.cycle)} · prochain : ${Utils.formatDate(sub.nextDate, { year: 'numeric' })}</small></div><strong>${Utils.money(sub.amount)}</strong>${!sub.active ? badge('Suspendu') : ''}<div class="row-actions">${actionButton('subscription-edit', sub.id)}${actionButton('subscription-delete', sub.id, 'trash', 'Supprimer l’abonnement')}</div></div>`).join('')}</div>` : '<p class="muted">Aucun abonnement suivi. Les renouvellements pourront déclencher une notification.</p>'}</article>
    <article class="panel reveal"><header class="panel-header"><div><span class="micro-label">ENGAGEMENTS</span><h2>Dettes & remboursements</h2></div><button class="button ghost small" data-action="debt-new">${icon('plus', 15)} Ajouter</button></header>${debts.length ? `<div class="debt-list">${debts.map(debt => { const ratio = debt.amount > 0 ? debt.paid / debt.amount * 100 : 0; return `<div class="debt-row"><div><strong>${Utils.esc(debt.name)}</strong><small>${Utils.esc(debt.creditor || 'Créancier non renseigné')} · ${debt.rate || 0} %</small></div><strong>${Utils.money(Math.max(0, debt.amount - debt.paid))}<small> restants</small></strong>${progressBar(ratio, `${Utils.money(debt.paid)} remboursés`)}<div class="row-actions">${debt.amount - debt.paid > 0 ? `<button class="button ghost tiny" data-action="debt-payment" data-id="${debt.id}">Versement</button>` : badge('Soldée', 'terme')}${actionButton('debt-edit', debt.id)}${actionButton('debt-delete', debt.id, 'trash', 'Supprimer la dette')}</div></div>`; }).join('')}</div>` : '<p class="muted">Aucune dette enregistrée. Cette section reste volontairement vide tant que vous ne saisissez rien.</p>'}</article></section>
  </div>`;
}

function eventPill(event, compact = false) {
  return `<button class="calendar-event ${compact ? 'compact' : ''}" style="--event-color:${eventColors[event.category] || eventColors.Autre}" data-action="event-edit" data-id="${event.id}" title="${Utils.esc(event.title)} · ${Utils.esc(event.description || '')}"><i></i><span>${compact ? '' : `${Utils.esc(event.start)} · `}${Utils.esc(event.title)}</span></button>`;
}

function monthCalendar(events) {
  const cursor = ViewState.calendarCursor; const year = cursor.getFullYear(), month = cursor.getMonth();
  const first = new Date(year, month, 1); const start = new Date(first); const shift = (first.getDay() + 6) % 7; start.setDate(start.getDate() - shift);
  const days = Array.from({ length: 42 }, (_, i) => { const date = new Date(start); date.setDate(start.getDate() + i); return date; });
  return `<div class="month-calendar panel reveal"><div class="weekday-row">${['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'].map(d => `<span>${d}</span>`).join('')}</div><div class="month-grid">${days.map(day => { const key = Utils.iso(day); const dayEvents = events.filter(e => e.date === key).sort((a, b) => a.start.localeCompare(b.start)); const outside = day.getMonth() !== month; return `<div class="calendar-day ${outside ? 'outside' : ''} ${key === Utils.iso() ? 'today' : ''}"><div class="day-head"><button data-action="calendar-day" data-date="${key}" class="day-number">${day.getDate()}</button><button class="day-add" data-action="event-new" data-date="${key}" aria-label="Ajouter un événement le ${key}">${icon('plus', 13)}</button></div><div class="day-events">${dayEvents.slice(0, 3).map(e => eventPill(e, true)).join('')}${dayEvents.length > 3 ? `<button class="more-events" data-action="calendar-day" data-date="${key}">+ ${dayEvents.length - 3} autre(s)</button>` : ''}</div></div>`; }).join('')}</div></div>`;
}

function weekCalendar(events) {
  const start = Utils.startOfWeek(ViewState.calendarCursor); const days = Array.from({ length: 7 }, (_, i) => { const d = new Date(start); d.setDate(d.getDate() + i); return d; });
  return `<div class="week-calendar panel reveal">${days.map(day => { const key = Utils.iso(day); const dayEvents = events.filter(e => e.date === key).sort((a, b) => a.start.localeCompare(b.start)); return `<section class="week-day ${key === Utils.iso() ? 'today' : ''}"><header><span>${new Intl.DateTimeFormat('fr-FR', { weekday: 'short' }).format(day)}</span><button data-action="calendar-day" data-date="${key}">${day.getDate()}</button></header><div>${dayEvents.length ? dayEvents.map(e => `<article class="week-event" style="--event-color:${eventColors[e.category] || eventColors.Autre}"><button data-action="event-edit" data-id="${e.id}"><time>${e.start}${e.end ? `–${e.end}` : ''}</time><strong>${Utils.esc(e.title)}</strong><small>${Utils.esc(e.category)}</small></button></article>`).join('') : '<span class="no-event">Libre</span>'}</div><button class="week-add" data-action="event-new" data-date="${key}">${icon('plus', 13)} Ajouter</button></section>`; }).join('')}</div>`;
}

function dayCalendar(events) {
  const key = Utils.iso(ViewState.calendarCursor); const dayEvents = events.filter(e => e.date === key).sort((a, b) => a.start.localeCompare(b.start));
  const hours = Array.from({ length: 17 }, (_, i) => i + 6);
  return `<div class="day-calendar panel reveal"><div class="day-timeline">${hours.map(hour => { const atHour = dayEvents.filter(e => Number(e.start.split(':')[0]) === hour); return `<div class="hour-row"><time>${String(hour).padStart(2, '0')}:00</time><div class="hour-slot"><button class="hour-add" data-action="event-new" data-date="${key}" data-time="${String(hour).padStart(2, '0')}:00" aria-label="Ajouter à ${hour} heures"></button>${atHour.map(event => `<article class="day-event" style="--event-color:${eventColors[event.category] || eventColors.Autre}"><button data-action="event-edit" data-id="${event.id}"><time>${event.start}${event.end ? ` – ${event.end}` : ''}</time><strong>${Utils.esc(event.title)}</strong><p>${Utils.esc(event.description || event.category)}</p><small>Rappel : ${Number(event.reminder) ? `${event.reminder} min avant` : 'désactivé'}</small></button></article>`).join('')}</div></div>`; }).join('')}</div>${!dayEvents.length ? `<div class="day-empty-note">${icon('calendar', 20)} Aucun événement ce jour. Cliquez sur une heure pour planifier.</div>` : ''}</div>`;
}

export function Calendar() {
  const events = Repo.list('events'); const cursor = ViewState.calendarCursor; const key = Utils.iso(cursor);
  const title = ViewState.calendarView === 'month' ? new Intl.DateTimeFormat('fr-FR', { month: 'long', year: 'numeric' }).format(cursor) : ViewState.calendarView === 'week' ? `Semaine du ${Utils.formatDate(Utils.startOfWeek(cursor), { year: 'numeric' })}` : Utils.formatLongDate(cursor);
  const add = `<button class="button primary" data-action="event-new" data-date="${key}">${icon('plus', 17)} Nouvel événement</button>`;
  return `<div class="page-view calendar-view">${sectionHeader('TEMPS / ENGAGEMENTS', 'Calendrier', 'Organisez vos rendez-vous, rappels et échéances projet au même endroit.', add)}
    <div class="calendar-toolbar panel reveal"><div class="calendar-nav"><button class="icon-button" data-action="calendar-prev" aria-label="Période précédente">${icon('left')}</button><button class="button ghost small" data-action="calendar-today">Aujourd’hui</button><button class="icon-button" data-action="calendar-next" aria-label="Période suivante">${icon('right')}</button><h2>${Utils.esc(title)}</h2></div><div class="segmented"><button class="${ViewState.calendarView === 'month' ? 'active' : ''}" data-action="calendar-view" data-view="month">Mois</button><button class="${ViewState.calendarView === 'week' ? 'active' : ''}" data-action="calendar-view" data-view="week">Semaine</button><button class="${ViewState.calendarView === 'day' ? 'active' : ''}" data-action="calendar-view" data-view="day">Jour</button></div></div>
    <div class="calendar-legend reveal">${Object.entries(eventColors).map(([name, color]) => `<span><i style="background:${color}"></i>${name}</span>`).join('')}</div>
    ${ViewState.calendarView === 'week' ? weekCalendar(events) : ViewState.calendarView === 'day' ? dayCalendar(events) : monthCalendar(events)}
    <section class="upcoming-panel panel reveal"><header class="panel-header"><div><span class="micro-label">À L’HORIZON</span><h2>Prochains rendez-vous & échéances</h2></div><span class="result-count">${Selectors.upcomingEvents(50).length} à venir</span></header><div class="upcoming-list">${Selectors.upcomingEvents(5).map(event => `<button data-action="event-edit" data-id="${event.id}"><i style="background:${eventColors[event.category] || eventColors.Autre}"></i><time><strong>${Utils.formatDate(event.date)}</strong><small>${event.start}</small></time><span><strong>${Utils.esc(event.title)}</strong><small>${Utils.esc(event.category)} · rappel ${Number(event.reminder) ? `${event.reminder} min avant` : 'désactivé'}</small></span>${icon('chevron', 16)}</button>`).join('') || '<p class="muted">Aucun événement futur. Profitez de cet horizon dégagé.</p>'}</div></section>
  </div>`;
}

export function Devices() {
  const devices = Repo.list('devices'); const categories = Taxonomy.deviceCategories;
  const add = `<button class="button primary" data-action="device-new">${icon('plus', 17)} Ajouter un appareil</button>`;
  return `<div class="page-view devices-view">${sectionHeader('PARC / ÉTAT DÉCLARÉ', 'Appareils', 'Inventaire, garanties et vérifications physiques. La télémétrie distante n’est jamais devinée.', add)}
    <section class="live-probe panel reveal"><div class="probe-visual">${icon('cpu', 30)}<span class="live-pulse"></span></div><div><span class="micro-label">SONDE RÉELLE · CE NAVIGATEUR UNIQUEMENT</span><h2>Appareil exécutant PERSONAL OS</h2><p>Les informations ci-dessous proviennent des API du navigateur, si celles-ci les autorisent.</p></div><div class="probe-values"><div><span>Réseau du navigateur</span><strong id="probe-network">Lecture…</strong></div><div><span>Batterie de cet appareil</span><strong id="probe-battery">Non disponible</strong></div><div><span>Stockage navigateur</span><strong id="probe-storage">Non disponible</strong></div></div><button class="button ghost small" data-action="device-probe">${icon('refresh', 15)} Relire maintenant</button></section>
    <div class="device-disclosure reveal">${icon('info', 17)}<p>Pour les autres appareils, <strong>batterie, stockage et connexion sont indisponibles</strong>. Le statut affiché est une information manuelle, pas une mesure réseau. « Vérifier » enregistre seulement l’heure de votre contrôle déclaré.</p></div>
    <section class="device-category-strip reveal">${categories.map(category => `<div><span>${category}</span><strong>${devices.filter(d => d.category === category).length}</strong></div>`).join('')}</section>
    ${devices.length ? `<section class="card-grid device-grid">${devices.map(device => { const warrantyLate = device.warranty && device.warranty < Utils.iso(); return `<article class="device-card card reveal"><header><span class="project-icon">${icon(device.category === 'Ordinateur' ? 'cpu' : device.category === 'Véhicule' ? 'gauge' : device.category === 'Domotique' ? 'wifi' : 'cpu', 22)}</span><span class="device-status ${Utils.slug(device.status)}"><i></i>${Utils.esc(device.status)}</span><div class="row-actions">${actionButton('device-edit', device.id)}${actionButton('device-delete', device.id, 'trash', 'Supprimer l’appareil')}</div></header><span class="micro-label">${Utils.esc(device.category)}</span><h3>${Utils.esc(device.name)}</h3><p>${Utils.esc([device.brand, device.model].filter(Boolean).join(' · ') || 'Marque et modèle non renseignés')}</p><dl><div><dt>Acquisition</dt><dd>${device.purchaseDate ? Utils.formatDate(device.purchaseDate, { year: 'numeric' }) : 'Non renseignée'}</dd></div><div><dt>Garantie</dt><dd class="${warrantyLate ? 'warning-text' : ''}">${device.warranty ? `${Utils.formatDate(device.warranty, { year: 'numeric' })}${warrantyLate ? ' · expirée' : ''}` : 'Non renseignée'}</dd></div><div><dt>Dernière vérification</dt><dd>${device.lastCheck ? Utils.formatDateTime(device.lastCheck) : 'Jamais vérifié'}</dd></div><div><dt>Télémétrie</dt><dd>Batterie / stockage / connexion : N/D</dd></div></dl>${device.notes ? `<blockquote>${Utils.esc(device.notes)}</blockquote>` : ''}<footer><button class="button ghost small" data-action="device-check" data-id="${device.id}">${icon('check', 15)} Confirmer une vérification manuelle</button></footer></article>`; }).join('')}</section>` : emptyState('Aucun appareil inventorié', 'Ajoutez vos appareils avec leurs dates d’achat, garanties et notes de vérification.', add, 'cpu')}
  </div>`;
}

function notificationRow(notification) {
  const tone = notification.type === 'Critique' || notification.priority === 'Critique' ? 'critical' : notification.type === 'Alerte' ? 'warning' : notification.type === 'Rappel' ? 'reminder' : 'info';
  return `<article class="notification-row ${notification.read ? 'read' : 'unread'} ${tone} reveal"><i class="notification-marker"></i><span class="notification-icon">${icon(tone === 'info' ? 'info' : tone === 'reminder' ? 'bell' : 'alert', 19)}</span><div class="notification-copy"><div><h3>${Utils.esc(notification.title)}</h3>${badge(notification.type, priorityTone(notification.priority))}<span class="priority-text">${Utils.esc(notification.priority)}</span></div><p>${Utils.esc(notification.body || 'Aucun détail supplémentaire.')}</p><small>${Utils.esc(notification.source)} · ${Utils.formatDateTime(notification.date)} · ${Utils.relative(notification.date)}</small></div><div class="notification-actions">${notification.reminderId ? `<button class="button ghost tiny" data-action="reminder-snooze" data-id="${notification.reminderId}">+15 min</button><button class="button primary tiny" data-action="reminder-done" data-id="${notification.reminderId}">C’est fait</button>` : ''}<button class="button ghost tiny" data-action="notification-read" data-id="${notification.id}">${notification.read ? 'Marquer non lu' : 'Marquer comme lu'}</button>${actionButton('notification-delete', notification.id, 'trash', 'Supprimer la notification')}</div></article>`;
}

export function Notifications() {
  const all = [...Repo.list('notifications')].sort((a, b) => new Date(b.date) - new Date(a.date));
  let filtered = ViewState.notificationTab === 'unread' ? all.filter(n => !n.read) : all;
  if (ViewState.notificationType !== 'Tous') filtered = filtered.filter(n => n.type === ViewState.notificationType);
  const automations = Repo.list('automations'); const rules = Repo.list('rules');
  const add = `<button class="button ghost" data-action="notification-new">${icon('plus', 17)} Nouvelle notification</button><button class="button primary" data-action="notifications-read-all">${icon('check', 17)} Tout marquer comme lu</button>`;
  return `<div class="page-view notifications-view">${sectionHeader('SIGNAUX / PRIORITÉS', 'Centre de notifications', 'Alertes générées par vos données, historique des règles et annonces vocales sans doublon.', add)}
    <section class="notification-overview reveal"><div><span>Non lues</span><strong>${all.filter(n => !n.read).length}</strong></div><div><span>Critiques</span><strong>${all.filter(n => !n.read && (n.type === 'Critique' || n.priority === 'Critique')).length}</strong></div><div><span>Règles actives</span><strong>${rules.filter(r => r.enabled).length}<small> / ${rules.length}</small></strong></div><div><span>Annonces vocales</span><strong>${Store.settings.autoAnnounce && Store.settings.voiceEnabled ? 'ON' : 'OFF'}</strong></div></section>
    <div class="view-toolbar reveal"><div class="segmented"><button class="${ViewState.notificationTab === 'all' ? 'active' : ''}" data-action="notification-tab" data-tab="all">Toutes <b>${all.length}</b></button><button class="${ViewState.notificationTab === 'unread' ? 'active' : ''}" data-action="notification-tab" data-tab="unread">Non lues <b>${all.filter(n => !n.read).length}</b></button><button class="${ViewState.notificationTab === 'automations' ? 'active' : ''}" data-action="notification-tab" data-tab="automations">Automatisations <b>${automations.length}</b></button></div><div class="toolbar-right">${ViewState.notificationTab !== 'automations' ? `<label class="compact-label">Type<select data-view-filter="notification-type">${['Tous', 'Information', 'Rappel', 'Alerte', 'Critique'].map(type => `<option ${ViewState.notificationType === type ? 'selected' : ''}>${type}</option>`).join('')}</select></label><button class="button ghost small" data-action="notifications-clear-read">Supprimer les lues</button>` : `<button class="button ghost small" data-action="automation-scan">${icon('refresh', 15)} Vérifier les règles</button>`}</div></div>
    ${ViewState.notificationTab === 'automations' ? `<section class="automation-layout"><article class="panel reveal"><header class="panel-header"><div><span class="micro-label">DÉCLENCHEURS</span><h2>Règles du système</h2></div></header><div class="rule-list">${rules.map(rule => `<div class="rule-row"><span class="rule-icon">${icon('activity', 17)}</span><div><strong>${Utils.esc(rule.name)}</strong><p>${Utils.esc(rule.description)}</p></div><label class="switch-only"><input type="checkbox" data-rule-toggle="${rule.id}" ${rule.enabled ? 'checked' : ''} aria-label="Activer ${Utils.esc(rule.name)}"><span class="switch"><span></span></span></label></div>`).join('')}</div></article><article class="panel reveal"><header class="panel-header"><div><span class="micro-label">JOURNAL D’EXÉCUTION</span><h2>Dernières automatisations</h2></div></header><div class="automation-log">${automations.length ? automations.slice(0, 30).map(log => `<div><i></i><span><strong>${Utils.esc(log.name)}</strong><p>${Utils.esc(log.detail)}</p><small>${Utils.formatDateTime(log.date)}</small></span></div>`).join('') : '<p class="muted">Aucune règle exécutée pour le moment. Les déclencheurs laisseront ici une trace datée.</p>'}</div></article></section>` : `<section class="notification-list">${filtered.length ? filtered.map(notificationRow).join('') : emptyState('Aucun signal dans cette vue', 'Les rappels d’échéance et événements de l’application apparaîtront ici.', '<button class="button ghost" data-action="notification-new">Créer une notification manuelle</button>', 'bell')}</section>`}
    <section class="voice-announcement-settings panel reveal"><div>${icon('volume', 22)}<span><strong>Annonces vocales automatiques</strong><small>Chaque notification n’est annoncée qu’une fois. Les horaires silencieux sont respectés.</small></span></div><button class="button ghost small" data-action="settings-voice">Configurer la voix et les horaires</button></section>
  </div>`;
}

export function Assistant() {
  const history = [...Repo.list('assistant')].sort((a, b) => new Date(a.date) - new Date(b.date));
  const recognition = Boolean(navigator.mediaDevices?.getUserMedia && (globalThis.AudioContext || globalThis.webkitAudioContext));
  return `<div class="page-view assistant-view">${sectionHeader('COPILOTE PERSONNEL / SOPHIE', Store.settings.assistantName || 'Sophie', 'Votre copilote vocal : elle consulte vos modules, mémorise ce que vous lui confiez et exécute les actions autorisées.', `<button class="button ghost" data-action="search-open">${icon('search', 16)} Recherche</button><button class="button ghost" data-action="briefing-now">${icon('volume', 16)} Briefing</button><button class="button ghost" data-action="daily-report">Bilan du jour</button><button class="button ghost" data-action="weekly-report">Bilan semaine</button><button class="button ${Store.settings.voiceEnabled ? 'primary' : 'ghost'}" data-action="voice-enabled-toggle">${icon(Store.settings.voiceEnabled ? 'volume' : 'mute', 16)} Voix ${Store.settings.voiceEnabled ? 'ON' : 'OFF'}</button>`)}
    <section class="voice-console reveal">
      <div class="voice-stage"><div class="voice-status-line"><span class="live-pulse"></span><span id="assistant-status">PRÊT · MOTEUR DE COMMANDES LOCAL</span></div><div class="sophie-stage">${SophieAvatar({ size: 230, state: 'idle', caption: true, button: true })}</div><div class="sound-wave" id="sound-wave" aria-hidden="true">${Array.from({ length: 24 }, (_, i) => `<i style="--i:${i}"></i>`).join('')}</div><h2 id="voice-instruction">${recognition ? 'Touchez pour parler' : 'Microphone non disponible'}</h2><p id="voice-transcript">${recognition ? 'Reconnaissance locale Vosk · modèle français chargé au démarrage.' : 'Autorisez le microphone ou utilisez la saisie ci-dessous.'}</p><div class="voice-tech-status"><span class="${recognition ? 'available' : ''}">${icon(recognition ? 'check' : 'x', 14)} STT ${recognition ? 'Vosk · microphone disponible' : 'microphone indisponible'}</span><span class="${'speechSynthesis' in globalThis ? 'available' : ''}">${icon('speechSynthesis' in globalThis ? 'check' : 'x', 14)} TTS ${'speechSynthesis' in globalThis ? 'natif' : 'indisponible'}</span><button class="provider-chip" data-action="voice-mode-info">${icon('music', 13)} ${Utils.esc(TTS.providers()[TTS.status().active])}${TTS.status().circuit ? ' · repli actif' : ''}</button></div></div>
      <div class="voice-side"><div class="voice-capabilities"><span class="micro-label">COMMANDES OPÉRATIONNELLES</span><h3>Essayez une instruction</h3><div class="command-chips">${['Hé Sophie, qu’est-ce que j’ai aujourd’hui ?', 'Fais-moi le bilan de ma semaine', 'Hé Sophie, j’ai fait 20 pompes et 45 secondes de gainage', 'J’ai dépensé 25 euros en courses', 'Ajoute une idée à PitLane : développer une offre de sponsoring', 'Retrouve la dernière note sur PitLane', 'Mémorise que je préfère les séances le matin', 'Active le mode concentration', 'Mets un minuteur de 5 minutes', 'Quel est mon budget restant ?'].map(command => `<button data-action="voice-command" data-command="${Utils.esc(command)}">${Utils.esc(command)}${icon('arrow', 13)}</button>`).join('')}</div><p>${icon('info', 14)} L’assistant reconnaît des intentions définies localement. Une phrase inconnue est signalée honnêtement, sans réponse inventée.</p></div><form class="voice-text-form" data-form="voice-command"><label for="voice-command-input">Commande texte</label><div><input id="voice-command-input" name="command" required maxlength="240" placeholder="Ex. Quel est mon budget restant ?" autocomplete="off"><button class="button primary" type="submit" aria-label="Exécuter la commande">${icon('send', 18)}</button></div></form></div>
    </section>
    <section class="sophie-panels"><article class="panel reveal"><header class="panel-header"><div><span class="micro-label">MÉMOIRE PERSONNELLE</span><h2>Ce que Sophie conserve</h2><p>Vous contrôlez chaque information : modification ou suppression à tout moment.</p></div><button class="button ghost small" data-action="sophie-memory-add">${icon('plus', 15)} Mémoriser</button></header><div class="memory-list">${Sophie.memory.list().length ? Sophie.memory.list().slice(0, 8).map(item => `<div class="memory-item"><span class="badge ${Utils.slug(item.kind)}">${Utils.esc(item.kind)}</span><p>${Utils.esc(item.text)}</p><small>${Utils.formatDateTime(item.date)}</small><button class="icon-button subtle" data-action="sophie-memory-delete" data-id="${item.id}" aria-label="Oublier cette information">${icon('trash', 15)}</button></div>`).join('') : '<p class="muted">Aucune information mémorisée. Dites « Hé Sophie, mémorise que… » ou utilisez le bouton ci-dessus.</p>'}</div></article>
    <article class="panel reveal"><header class="panel-header"><div><span class="micro-label">OUTILS AUTORISÉS · FUNCTION CALLING</span><h2>Actions exécutables par Sophie</h2><p>Les opérations sensibles demandent une confirmation explicite avant exécution.</p></div></header><div class="tools-grid">${Sophie.tools.map(tool => `<div class="tool-item ${tool.sensitive ? 'sensitive' : ''}"><span>${icon(tool.sensitive ? 'lock' : 'check', 14)}</span><div><strong>${Utils.esc(tool.label)}</strong><small>${Utils.esc(tool.module)}${tool.sensitive ? ' · confirmation requise' : ''}</small></div></div>`).join('')}</div></article>
    <article class="panel reveal"><header class="panel-header"><div><span class="micro-label">COMMANDES PERSONNALISÉES</span><h2>« Hey Sophie … » → votre réponse</h2><p>Vous écrivez ce que Sophie doit dire. Vos commandes passent avant le moteur intégré.</p></div><button class="button ghost small" data-action="command-new">${icon('plus', 15)} Nouvelle commande</button></header><div class="custom-commands">${(Store.data.customCommands || []).length ? Store.data.customCommands.map(command => `<div class="custom-command"><div class="cmd-triggers">${(command.triggers || []).map(t => `<span>« ${Utils.esc(t)} »</span>`).join('')}</div><p class="cmd-response">${Utils.esc(command.response)}</p><small>${command.voice ? 'Réponse vocale' : 'Réponse silencieuse'}${command.action ? ` · ouvre ${Utils.esc(command.action)}` : ''}</small><div class="cmd-actions"><button class="button ghost tiny" data-action="command-test" data-id="${command.id}">${icon('volume', 14)} Tester</button><button class="button ghost tiny" data-action="command-edit" data-id="${command.id}">Modifier</button><button class="button ghost tiny danger" data-action="command-delete" data-id="${command.id}">Supprimer</button></div></div>`).join('') : '<p class="muted">Aucune commande personnalisée. Exemple : déclencheur « bonne nuit », réponse « Bonne nuit {nom}, à demain. »</p>'}</div></article>
    <article class="panel reveal"><header class="panel-header"><div><span class="micro-label">RÉGLAGES RAPIDES</span><h2>Voix, activation et briefings</h2></div></header><div class="setting-row"><div><strong>Activation « Hé Sophie »</strong><p>Détection locale dans le transcript, sans serveur. Nécessite une application native Android pour l’écoute application fermée.</p></div><label class="switch-only"><input type="checkbox" data-setting="wakeWordEnabled" ${Store.settings.wakeWordEnabled ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row"><div><strong>Fournisseur vocal</strong><p>Automatique : ElevenLabs via proxy sécurisé, puis repli natif en cas de quota ou d’indisponibilité.</p></div><select data-setting="voiceProvider"><option value="auto" ${Store.settings.voiceProvider === 'auto' ? 'selected' : ''}>Automatique</option><option value="elevenlabs" ${Store.settings.voiceProvider === 'elevenlabs' ? 'selected' : ''}>ElevenLabs uniquement</option><option value="native" ${Store.settings.voiceProvider === 'native' ? 'selected' : ''}>Voix native uniquement</option></select></div><div class="setting-row"><div><strong>Endpoint du proxy ElevenLabs</strong><p>URL sécurisée qui détient la clé (jamais la clé elle-même). Ex. http://localhost:8080/api/tts ou /api/tts sur votre hébergement.</p></div><input type="url" value="${Utils.esc(Store.settings.elevenlabsEndpoint || '')}" data-setting="elevenlabsEndpoint" placeholder="https://votre-domaine/api/tts"></div><div class="setting-row"><div><strong>ID de voix ElevenLabs</strong><p>Votre voice ID (26 caractères). La clé API reste dans le fichier .env côté serveur.</p></div><input type="text" value="${Utils.esc(Store.settings.elevenlabsVoiceId || '')}" data-setting="elevenlabsVoiceId" placeholder="Kuy2kDCiyKmA79V9BbDr" maxlength="40"></div><div class="setting-row"><div><strong>Nom de l’assistante</strong><p>Affiché dans l’interface et utilisé dans ses réponses.</p></div><input type="text" value="${Utils.esc(Store.settings.assistantName || 'Sophie')}" data-setting="assistantName" maxlength="24"></div><div class="setting-row"><div><strong>Portrait de Sophie</strong><p>URL d’une image carrée (512×512 conseillé). Laissez vide pour conserver le portrait vectoriel intégré.</p></div><input type="url" value="${Utils.esc(Store.settings.sophiePortrait || '')}" data-setting="sophiePortrait" placeholder="https://…/sophie-portrait.png"></div><button class="button ghost small" data-action="tts-test">${icon('volume', 15)} Tester la voix ElevenLabs</button><div class="setting-row"><div><strong>Confirmation des actions sensibles</strong><p>Dépenses et suppressions nécessitent un « confirme » explicite.</p></div><label class="switch-only"><input type="checkbox" data-setting="sophieConfirmSensitive" ${Store.settings.sophieConfirmSensitive ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row"><div><strong>Briefing du matin</strong><p>Programme, météo, priorités et échéances.</p></div><label class="switch-inline"><input type="checkbox" data-setting="morningBriefing.enabled" ${Store.settings.morningBriefing?.enabled ? 'checked' : ''}><input type="time" value="${Utils.esc(Store.settings.morningBriefing?.time || '07:15')}" data-setting="morningBriefing.time"></label></div><div class="setting-row"><div><strong>Bilan hebdomadaire</strong><p>Réalisations, retards, progrès et priorités.</p></div><label class="switch-inline"><input type="checkbox" data-setting="weeklyReport.enabled" ${Store.settings.weeklyReport?.enabled ? 'checked' : ''}><input type="time" value="${Utils.esc(Store.settings.weeklyReport?.time || '19:00')}" data-setting="weeklyReport.time"></label></div><button class="button ghost small" data-action="focus-mode-toggle">${icon('gauge', 15)} Basculer le mode concentration</button></article></section>
    <section class="panel voice-history reveal"><header class="panel-header"><div><span class="micro-label">MÉMOIRE DE SESSION PERSISTANTE</span><h2>Historique des échanges</h2></div><button class="button ghost small" data-action="voice-history-clear" ${history.length ? '' : 'disabled'}>Effacer l’historique</button></header><div class="chat-history" id="chat-history">${history.length ? history.map(message => `<div class="chat-message ${message.role}"><span>${message.role === 'user' ? 'VOUS' : 'PERSONAL OS'}</span><p>${Utils.esc(message.text)}</p><time>${Utils.formatDateTime(message.date)}</time></div>`).join('') : '<p class="muted">Aucun échange. Les commandes et réponses seront conservées dans cet espace de données.</p>'}</div></section>
    <section class="integration-note panel reveal">${icon('lock', 22)}<div><h3>Connecteur IA préparé, non activé</h3><p>Le moteur actuel exécute des règles locales vérifiables. Une future clé API pourra alimenter un adaptateur séparé après consentement explicite. Aucune requête n’est envoyée à un modèle externe dans cette version.</p></div><span class="badge">MODE LOCAL</span></section>
  </div>`;
}

export function Journal() {
  const all = [...Repo.list('journal')].sort((a, b) => new Date(b.date) - new Date(a.date));
  const entries = ViewState.journalType === 'Tous' ? all : all.filter(entry => entry.type === ViewState.journalType);
  const add = `<button class="button primary" data-action="journal-new">${icon('plus', 17)} Nouvelle entrée</button>`;
  const successes = all.filter(e => e.type === 'Réussite').length, difficulties = all.filter(e => e.type === 'Difficulté').length;
  return `<div class="page-view journal-view">${sectionHeader('MÉMOIRE / RÉFLEXION', 'Journal personnel', 'Notes, événements, réussites et difficultés : une mémoire datée pour éclairer vos décisions.', add)}
    <section class="journal-overview panel reveal"><div class="journal-quote"><span class="micro-label">CAPSULE PERSONNELLE</span><blockquote>« Ce qui est noté peut être relu, compris, puis amélioré. »</blockquote><p>${all.length} entrée${all.length > 1 ? 's' : ''} conservée${all.length > 1 ? 's' : ''} sur cet appareil.</p></div><div class="journal-stats"><div><strong>${successes}</strong><span>Réussites</span></div><div><strong>${difficulties}</strong><span>Difficultés</span></div><div><strong>${all.filter(e => e.date?.startsWith(Utils.monthKey())).length}</strong><span>Ce mois-ci</span></div></div></section>
    <div class="filter-bar reveal"><div class="filter-group"><label>Type d’entrée<select data-view-filter="journal-type"><option>Tous</option>${Taxonomy.journalTypes.map(type => `<option ${ViewState.journalType === type ? 'selected' : ''}>${type}</option>`).join('')}</select></label></div><span class="result-count">${entries.length} entrée${entries.length > 1 ? 's' : ''}</span></div>
    ${entries.length ? `<section class="journal-timeline">${entries.map(entry => `<article class="journal-entry reveal"><div class="journal-date"><strong>${new Date(entry.date).getDate()}</strong><span>${new Intl.DateTimeFormat('fr-FR', { month: 'short' }).format(new Date(entry.date))}</span><time>${Utils.formatTime(entry.date)}</time></div><i class="journal-node"></i><div class="journal-entry-card"><header>${badge(entry.type)}<div class="row-actions">${actionButton('journal-edit', entry.id)}${actionButton('journal-delete', entry.id, 'trash', 'Supprimer l’entrée')}</div></header><h3>${Utils.esc(entry.title)}</h3><p>${Utils.esc(entry.text || 'Aucun contenu complémentaire.')}</p>${entry.tags?.length ? `<footer>${entry.tags.map(tag => `<span>#${Utils.esc(tag)}</span>`).join('')}</footer>` : ''}</div></article>`).join('')}</section>` : emptyState('Aucune entrée dans cette vue', all.length ? 'Choisissez un autre type pour consulter votre historique.' : 'Commencez par une note, une réussite ou une difficulté du jour.', add, 'book')}
  </div>`;
}

function settingsTabs() {
  const tabs = [['general', 'Général', 'settings'], ['widgets', 'Widgets', 'dashboard'], ['voice', 'Voix & alertes', 'volume'], ['data', 'Données & PWA', 'lock']];
  return `<div class="settings-tabs">${tabs.map(([id, label, iconName]) => `<button class="${ViewState.settingsTab === id ? 'active' : ''}" data-action="settings-tab" data-tab="${id}">${icon(iconName, 17)}${label}</button>`).join('')}</div>`;
}

export function Settings() {
  const s = Store.settings; const tab = ViewState.settingsTab;
  const widgets = s.widgets;
  return `<div class="page-view settings-view">${sectionHeader('SYSTÈME / CONFIGURATION', 'Paramètres', 'Personnalisez le poste de commande, les alertes et la conservation de vos données.', `<span class="settings-version">CORE ${APP_VERSION}</span>`)}${settingsTabs()}
    ${tab === 'general' ? `<section class="settings-layout"><article class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">APPARENCE</span><h2>Interface & accentuation</h2></div></header><div class="setting-row"><div><strong>Couleur d’accentuation principale</strong><p>Utilisée pour les actions, la progression et les états actifs.</p></div><div class="color-setting"><input type="color" value="${Utils.esc(s.accent)}" data-setting="accent" aria-label="Couleur principale"><code>${Utils.esc(s.accent)}</code></div></div><div class="setting-row"><div><strong>Accent secondaire</strong><p>Graphiques, informations et dégradés discrets.</p></div><div class="color-setting"><input type="color" value="${Utils.esc(s.accent2)}" data-setting="accent2" aria-label="Couleur secondaire"><code>${Utils.esc(s.accent2)}</code></div></div><div class="accent-presets"><button data-action="accent-preset" data-accent="#37D6A0" data-accent2="#35BDE0" style="--preset:#37D6A0">Émeraude</button><button data-action="accent-preset" data-accent="#35BDE0" data-accent2="#65A9FF" style="--preset:#35BDE0">Cyan</button><button data-action="accent-preset" data-accent="#E7C873" data-accent2="#FF9A5A" style="--preset:#E7C873">Ambre</button><button data-action="accent-preset" data-accent="#A78BFA" data-accent2="#35BDE0" style="--preset:#A78BFA">Violet</button></div><div class="setting-row"><div><strong>Animations de l’interface</strong><p>Le réglage système « réduire les animations » reste toujours prioritaire.</p></div><label class="switch-only"><input type="checkbox" data-setting="animations" ${s.animations ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row"><div><strong>Variante du thème sombre</strong><p>Le mode sombre permanent est conservé dans les deux variantes.</p></div><select data-setting="theme"><option value="nocturne" ${s.theme !== 'contraste' ? 'selected' : ''}>Nocturne</option><option value="contraste" ${s.theme === 'contraste' ? 'selected' : ''}>Contraste renforcé</option></select></div><div class="setting-row"><div><strong>Halos lumineux réduits</strong><p>Atténue les ombres colorées pour un affichage plus sobre.</p></div><label class="switch-only"><input type="checkbox" data-setting="reducedGlow" ${s.reducedGlow ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row"><div><strong>Densité d’affichage</strong><p>Adapte l’espacement aux tablettes et petits écrans.</p></div><select data-setting="density"><option value="confortable" ${s.density === 'confortable' ? 'selected' : ''}>Confortable</option><option value="compacte" ${s.density === 'compacte' ? 'selected' : ''}>Compacte</option></select></div></article>
    <article class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">AFFICHAGE</span><h2>Tablette & plein écran</h2></div></header><p class="settings-description">En plein écran, la tablette peut servir de poste de commande permanent sur un bureau ou un support mural. La sortie reste accessible par le même bouton ou la touche Échap du système.</p><button class="button primary" data-action="fullscreen">${icon('expand', 17)} Basculer en plein écran</button><div class="setting-row"><div><strong>Vue chargée au démarrage</strong><p>L’application monte directement cette vue, sans écran d’ouverture.</p></div><select data-setting="startupSection"><option value="last" ${s.startupSection === 'last' ? 'selected' : ''}>Dernière vue ouverte</option><option value="dashboard" ${s.startupSection === 'dashboard' ? 'selected' : ''}>Dashboard compact</option><option value="calendar" ${s.startupSection === 'calendar' ? 'selected' : ''}>Calendrier</option><option value="assistant" ${s.startupSection === 'assistant' ? 'selected' : ''}>Sophie</option><option value="journal" ${s.startupSection === 'journal' ? 'selected' : ''}>Journal</option></select></div><div class="setting-row"><div><strong>Démarrage direct sans ouverture</strong><p>Aucune animation d’entrée ni écran d’accueil : le cockpit est utilisable immédiatement.</p></div><label class="switch-only"><input type="checkbox" data-setting="silentBoot" ${s.silentBoot !== false ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row"><div><strong>Affichage permanent</strong><p>Maintient l’écran actif (mode veille / support mural). Nécessite le navigateur en premier plan.</p></div><label class="switch-only"><input type="checkbox" data-setting="wakeLock" ${s.wakeLock ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="divider"></div><header class="panel-header"><div><span class="micro-label">MÉTÉO RÉELLE</span><h2>Position Open-Meteo</h2></div></header><div class="form-grid settings-form"><div class="form-field"><label for="weather-label">Nom du lieu</label><input id="weather-label" value="${Utils.esc(s.weather.label)}" data-weather-setting="label" placeholder="Ex. Domicile"></div><div class="form-field"><label>Latitude</label><input type="number" step="any" value="${Utils.esc(s.weather.lat)}" data-weather-setting="lat"></div><div class="form-field"><label>Longitude</label><input type="number" step="any" value="${Utils.esc(s.weather.lon)}" data-weather-setting="lon"></div></div><div class="button-row"><button class="button ghost small" data-action="weather-locate">${icon('target', 15)} Utiliser ma position</button><button class="button primary small" data-action="weather-refresh">${icon('refresh', 15)} Actualiser la météo</button></div><p class="settings-hint">La localisation n’est demandée qu’après votre action. Les coordonnées et le dernier relevé sont conservés localement.</p></article></section>` : ''}
    ${tab === 'widgets' ? `<section class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">COCKPIT MODULABLE</span><h2>Ordre, visibilité et dimensions</h2><p>L’ordre ci-dessous est aussi celui du glisser-déposer sur le Dashboard.</p></div><button class="button ghost small" data-action="widgets-reset">Réinitialiser la disposition</button></header><div class="widget-settings-list">${widgets.map((widget, index) => `<div class="widget-setting-row"><span class="widget-order">${String(index + 1).padStart(2, '0')}</span><div><strong>${WIDGET_LABELS[widget.id] || widget.id}</strong><small>${widget.hidden ? 'Masqué' : `Visible · taille ${widget.size}`}</small></div><div class="widget-order-actions"><button class="icon-button" data-action="widget-up" data-id="${widget.id}" ${index === 0 ? 'disabled' : ''} aria-label="Monter">${icon('left', 16)}</button><button class="icon-button" data-action="widget-down" data-id="${widget.id}" ${index === widgets.length - 1 ? 'disabled' : ''} aria-label="Descendre">${icon('right', 16)}</button></div><select data-widget-size="${widget.id}" aria-label="Taille du widget"><option value="small" ${widget.size === 'small' ? 'selected' : ''}>Compact</option><option value="medium" ${widget.size === 'medium' ? 'selected' : ''}>Moyen</option><option value="large" ${widget.size === 'large' ? 'selected' : ''}>Large</option></select><label class="switch-only"><input type="checkbox" data-widget-visible="${widget.id}" ${!widget.hidden ? 'checked' : ''} aria-label="Afficher le widget"><span class="switch"><span></span></span></label></div>`).join('')}</div><div class="widget-integrations"><article><span>${icon('music', 20)}</span><div><strong>Contenu Spotify</strong><p>${s.spotifyUrl ? 'Un lien est configuré. Vous pouvez le remplacer ou le retirer depuis cette fenêtre.' : 'Aucun contenu configuré. Le widget reste vide tant que vous ne fournissez pas de lien.'}</p></div><button class="button ghost small" data-action="spotify-configure">Configurer</button></article><article><span>${icon('clock', 20)}</span><div><strong>Cycle Focus</strong><p>${s.focus?.durations?.work || 25} min de concentration · ${s.focus?.durations?.break || 5} min de pause · ${s.focus?.cycles || 0} cycles terminés.</p></div><button class="button ghost small" data-action="focus-reset">Réinitialiser</button></article><article><span>${icon('flame', 20)}</span><div><strong>Habitudes</strong><p>${Store.data.habits.length} rituel${Store.data.habits.length > 1 ? 's' : ''} dans cet espace. Les validations sont propres à chaque espace de données.</p></div><button class="button ghost small" data-action="habit-manage">Gérer</button></article></div><div class="settings-hint">${icon('grip', 16)} Sur le Dashboard, saisissez la poignée d’un widget pour le déplacer. La taille peut également être changée depuis chaque carte.</div></section>` : ''}
    ${tab === 'voice' ? `<section class="settings-layout"><article class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">PERSONAL VOICE</span><h2>Synthèse & annonces</h2></div></header><div class="setting-row"><div><strong>Réponses vocales</strong><p>Utilise une voix française disponible dans SpeechSynthesis.</p></div><label class="switch-only"><input type="checkbox" data-setting="voiceEnabled" ${s.voiceEnabled ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row"><div><strong>Annonces automatiques</strong><p>Lit les nouvelles notifications une seule fois.</p></div><label class="switch-only"><input type="checkbox" data-setting="autoAnnounce" ${s.autoAnnounce ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="setting-row vertical"><label for="voice-rate">Vitesse de parole <output id="voice-rate-output">${s.voiceRate}×</output></label><input id="voice-rate" type="range" min="0.6" max="1.6" step="0.1" value="${s.voiceRate}" data-setting="voiceRate"><label for="voice-pitch">Hauteur <output id="voice-pitch-output">${s.voicePitch}</output></label><input id="voice-pitch" type="range" min="0.6" max="1.6" step="0.1" value="${s.voicePitch}" data-setting="voicePitch"></div><div class="setting-row"><div><strong>Niveau annoncé automatiquement</strong><p>« Important » limite la parole aux priorités haute et critique.</p></div><select data-setting="announcementFrequency"><option value="all" ${s.announcementFrequency === 'all' ? 'selected' : ''}>Toutes les notifications</option><option value="important" ${s.announcementFrequency === 'important' ? 'selected' : ''}>Important uniquement</option><option value="critical" ${s.announcementFrequency === 'critical' ? 'selected' : ''}>Critique uniquement</option></select></div><div class="setting-row"><div><strong>Fréquence maximale des annonces</strong><p>Les annonces en attente sont espacées pour éviter une lecture continue.</p></div><select data-setting="announcementInterval"><option value="1" ${Number(s.announcementInterval) === 1 ? 'selected' : ''}>Toutes les minutes</option><option value="5" ${Number(s.announcementInterval || 5) === 5 ? 'selected' : ''}>Toutes les 5 minutes</option><option value="15" ${Number(s.announcementInterval) === 15 ? 'selected' : ''}>Toutes les 15 minutes</option><option value="30" ${Number(s.announcementInterval) === 30 ? 'selected' : ''}>Toutes les 30 minutes</option><option value="60" ${Number(s.announcementInterval) === 60 ? 'selected' : ''}>Une fois par heure</option></select></div><button class="button ghost" data-action="voice-test">${icon('volume', 17)} Tester une annonce française</button></article>
    <article class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">DISCRÉTION</span><h2>Horaires silencieux</h2></div></header><div class="setting-row"><div><strong>Activer la plage silencieuse</strong><p>Les notifications restent visibles, mais ne sont pas lues à voix haute.</p></div><label class="switch-only"><input type="checkbox" data-setting="quietEnabled" ${s.quietEnabled ? 'checked' : ''}><span class="switch"><span></span></span></label></div><div class="time-range"><label>Début<input type="time" value="${s.quietStart}" data-setting="quietStart"></label><span>à</span><label>Fin<input type="time" value="${s.quietEnd}" data-setting="quietEnd"></label></div><div class="quiet-preview">${icon('mute', 18)}<span>Silence vocal de <strong>${s.quietStart}</strong> à <strong>${s.quietEnd}</strong>${s.quietStart > s.quietEnd ? ' (nuit incluse)' : ''}.</span></div><div class="divider"></div><div class="setting-row"><div><strong>Notifications système du navigateur</strong><p>Nécessite une autorisation explicite. Indépendant des alertes internes.</p></div><button class="button ghost small" data-action="browser-notification-permission">Demander l’autorisation</button></div><p class="settings-hint" id="notification-permission-state">État actuel : ${'Notification' in globalThis ? Notification.permission : 'API indisponible'}</p></article></section>` : ''}
    ${tab === 'data' ? `<section class="settings-layout"><article class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">ESPACES SÉPARÉS</span><h2>Source de données active</h2></div></header><div class="workspace-options"><button class="${Store.mode === 'demo' ? 'active' : ''}" data-action="workspace-demo"><span>${icon('eye', 20)}</span><div><strong>Démonstration fictive</strong><p>Parcours complet clairement identifié, réinitialisable à tout moment.</p></div>${Store.mode === 'demo' ? badge('ACTIF') : ''}</button><button class="${Store.mode === 'real' ? 'active' : ''}" data-action="workspace-real"><span>${icon('lock', 20)}</span><div><strong>Mes données réelles</strong><p>Espace indépendant, initialement vide. Aucune entrée fictive n’y est copiée.</p></div>${Store.mode === 'real' ? badge('ACTIF') : ''}</button></div><div class="data-insight"><span>${Store.data.goals.length + Store.data.projects.length + Store.data.transactions.length + Store.data.events.length + Store.data.journal.length} enregistrements principaux dans l’espace actif</span><small>Dernière modification : ${Utils.formatDateTime(Store.data.meta.updatedAt)}</small></div><div class="divider"></div><div class="danger-zone"><h3>Réinitialisation ciblée</h3><p>La réinitialisation de la démonstration ne touche jamais vos données réelles, et inversement.</p><div class="button-row"><button class="button ghost small" data-action="reset-demo">Réinitialiser la démo</button><button class="button danger small" data-action="clear-real">Effacer mes données réelles</button></div></div></article>
    <article class="panel settings-panel reveal"><header class="panel-header"><div><span class="micro-label">PORTABILITÉ</span><h2>Sauvegarde & restauration</h2></div></header><p class="settings-description">L’export JSON contient les deux espaces, les réglages, l’historique et les automatisations. Conservez ce fichier dans un emplacement de confiance.</p><div class="button-row"><button class="button primary" data-action="data-export">${icon('download', 17)} Exporter une sauvegarde</button><button class="button ghost" data-action="data-import">${icon('upload', 17)} Importer une sauvegarde</button></div><div class="divider"></div><header class="panel-header"><div><span class="micro-label">APPLICATION PROGRESSIVE</span><h2>Installation & hors ligne</h2></div></header><p id="pwa-status" class="settings-description">Le service worker met en cache l’interface pour les consultations hors ligne. La météo nécessite naturellement une connexion.</p><button class="button ghost" data-action="pwa-install" id="pwa-install-button">${icon('download', 17)} Installer l’application</button><div class="storage-facts"><span>${icon('lock', 14)} Stockage : LocalStorage de ce navigateur</span><span>${icon('cloud', 14)} Synchronisation cloud : non configurée</span><span>${icon('cpu', 14)} Application Android native : non requise</span></div></article></section>
    <section class="panel documentation-panel reveal"><header class="panel-header"><div><span class="micro-label">PÉRIMÈTRE RÉEL</span><h2>Fonctionnel aujourd’hui / intégrations futures</h2></div></header><div class="documentation-grid"><div><h3>Opérationnel hors ligne</h3><ul><li>CRUD complet des modules et widgets dynamiques</li><li>Statistiques, graphiques, Kanban et calendrier</li><li>Notifications internes, règles et historique</li><li>Assistant local, export/import et cache PWA</li></ul></div><div><h3>Nécessite une API ou un service</h3><ul><li>Météo : Open-Meteo, déjà intégré avec consentement</li><li>Supabase : synchronisation multi-appareils à configurer</li><li>IA générative : aucune API configurée actuellement</li><li>Banque : aucun agrégateur connecté, aucune simulation</li></ul></div><div><h3>Nécessite Android natif ou une intégration</h3><ul><li>Télémétrie distante des autres appareils</li><li>Notifications push externes en arrière-plan</li><li>Micro et annonces lorsque l’application est fermée</li><li>Widgets Android sur l’écran d’accueil</li></ul></div></div></section>` : ''}
  </div>`;
}
